import requests
from lxml import html
import pandas as pd
import sqlite3
import os
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
        try:
            resp = requests.get(webpage_url, timeout=10)
            resp.raise_for_status()
            content = resp.content
        except requests.RequestException as e:
            raise requests.RequestException(f"Network error: {e}")
    else:
        try:
            with open(webpage_url, "rb") as f:
                content = f.read()
        except Exception as e:
            raise requests.RequestException(f"File read error: {e}")

    try:
        tree = html.fromstring(content)
    except Exception as e:
        raise requests.RequestException(f"HTML parse error: {e}")

    tables = tree.xpath("//table")
    if not tables:
        return 0
    table = tables[0]

    headers = []
    th_elements = table.xpath(".//th")
    if th_elements:
        headers = [th.text_content().strip() for th in th_elements]

    rows = []
    for tr in table.xpath(".//tr"):
        td_elements = tr.xpath(".//td")
        if not td_elements:
            continue
        row_data = [td.text_content().strip() for td in td_elements]
        rows.append(row_data)

    if not rows:
        return 0

    df = pd.DataFrame(rows, columns=headers if headers else None)

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(df)

